// Writes the open-source list shown in Settings → About. Run after changing
// packages/app dependencies; `--check` fails when the generated file is stale.
import { format } from "oxfmt";
import { existsSync, readFileSync, realpathSync, writeFileSync } from "node:fs";
import { dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const appRoot = join(repoRoot, "packages/app");
const target = join(appRoot, "src/screens/settings/about/open-source.generated.ts");

function readJson(path) {
  return JSON.parse(readFileSync(path, "utf8"));
}

function resolvePackageDir(name) {
  for (const base of [appRoot, repoRoot]) {
    const dir = join(base, "node_modules", name);
    if (existsSync(join(dir, "package.json"))) return realpathSync(dir);
  }
  throw new Error(`Cannot resolve ${name}; run npm install first`);
}

function licenseOf(pkg) {
  if (typeof pkg.license === "string") return pkg.license;
  if (pkg.license?.type) return pkg.license.type;
  if (Array.isArray(pkg.licenses)) return pkg.licenses.map((entry) => entry.type).join(" OR ");
  throw new Error(`${pkg.name} declares no license`);
}

function homepageOf(pkg) {
  const repository = typeof pkg.repository === "string" ? pkg.repository : pkg.repository?.url;
  const candidates = [repository, pkg.homepage].filter(Boolean);
  for (const raw of candidates) {
    const url = raw
      .replace(/^git\+/, "")
      .replace(/^git:\/\//, "https://")
      .replace(/^ssh:\/\/git@/, "https://")
      .replace(/^git@github\.com:/, "https://github.com/")
      .replace(/^github:/, "https://github.com/")
      .replace(/\.git$/, "")
      .replace(/#.*$/, "");
    if (/^https?:\/\//.test(url)) return url;
    if (/^[\w.-]+\/[\w.-]+$/.test(url)) return `https://github.com/${url}`;
  }
  return `https://www.npmjs.com/package/${pkg.name}`;
}

const appPackage = readJson(join(appRoot, "package.json"));
const packages = [];
for (const name of Object.keys(appPackage.dependencies ?? {}).sort()) {
  const dir = resolvePackageDir(name);
  // Workspace packages are this repository, covered by the project license.
  if (!relative(repoRoot, dir).split(sep).includes("node_modules")) continue;
  const pkg = readJson(join(dir, "package.json"));
  packages.push({
    name,
    version: pkg.version,
    license: licenseOf(pkg),
    url: homepageOf(pkg),
  });
}

const projectLicense = readFileSync(join(repoRoot, "LICENSE"), "utf8").trim();
const projectNotice = readFileSync(join(repoRoot, "NOTICE"), "utf8").trim();

const rawOutput = `// Generated by npm run licenses:sync. Edit packages/app/package.json, LICENSE or NOTICE.
export interface ThirdPartyPackage {
  name: string;
  version: string;
  license: string;
  url: string;
}

export const THIRD_PARTY_PACKAGES: readonly ThirdPartyPackage[] = ${JSON.stringify(packages, null, 2)};

export const PROJECT_LICENSE_TEXT = ${JSON.stringify(projectLicense)};

export const PROJECT_NOTICE_TEXT = ${JSON.stringify(projectNotice)};
`;

const { code: output, errors } = await format(target, rawOutput, { printWidth: 100 });
if (errors.length) throw new Error("Invalid generated open-source list");
if (process.argv.includes("--check")) {
  if (!existsSync(target) || readFileSync(target, "utf8") !== output) {
    throw new Error("Stale open-source list: run npm run licenses:sync");
  }
} else {
  writeFileSync(target, output);
}
